/**
 * Settings built into the app. The browser talks to Keycloak directly and to the API through the same
 * origin (/api is proxied by the dev server or by nginx), so no CORS is needed.
 *
 * What changes per environment (the Keycloak issuer) is read at startup from /config.json instead:
 * `public/config.json` in development, generated by nginx from environment variables in the container.
 */
export const appSettings = {
  keycloak: {
    clientId: 'ledger-web',
  },
  /** Where the per-environment settings are served (absolute: the builds live under /en/ and /es/). */
  runtimeConfigUrl: '/config.json',
  /** How long to keep checking an asynchronous operation (loan, split, settlement). */
  operationTimeoutMs: 60_000,
  operationPollMs: 1_000,
} as const;

/** Contents of /config.json. */
export interface RuntimeConfig {
  /** e.g. http://localhost:8080/realms/ledger or https://auth.example.com/realms/ledger */
  keycloakIssuer: string;
}
